INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein lineares Gleichungssystem immer eine eindeutige Lösung hat?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Koeffizienten und Unabhängigkeit"}, {"text": "Ja", "correct": false, "because": "Kann keine oder unendlich viele Lösungen haben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium prüfe ich, um zu wissen, ob ein Gleichungssystem lösbar ist?', 3, '[{"text": "Determinante ungleich null", "correct": true, "because": "Zeigt eindeutige Lösung"}, {"text": "Hohe Koeffizienten", "correct": false, "because": "Irrelevant für Lösbarkeit"}, {"text": "Ganze Zahlen", "correct": false, "because": "Nicht entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei einer numerischen Methode für lineare Systeme entscheidend?', 5, '[{"text": "Pivotisierung", "correct": true, "because": "Vermeidet Division durch null"}, {"text": "Rückwärtseinsetzen", "correct": true, "because": "Berechnet Lösungen"}, {"text": "Zufällige Reihenfolge", "correct": false, "because": "Führt zu Fehlern"}, {"text": "Rundung auf Ganzzahl", "correct": false, "because": "Verfälscht Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Diagonalmatrix erleichtert die Lösung. b) Jede Matrix ist direkt lösbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) erfordert Umformung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein lineares System effizient lösen will?', 4, '[{"text": "Numerische Stabilität", "correct": false, "because": "Schlüssel für Genauigkeit"}, {"text": "Matrixstruktur", "correct": false, "because": "Beeinflusst Methode"}, {"text": "Farbe der Ausgabe", "correct": true, "because": "Irrelevant für Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass jede Matrix direkt in eine Dreiecksmatrix umgewandelt werden kann. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Durch elementare Umformungen"}, {"text": "Nein", "correct": false, "because": "Möglich bei regulären Matrizen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um eine Matrix für die Lösung vorzubereiten?', 3, '[{"text": "Zeilenvertauschung", "correct": true, "because": "Optimiert Pivot-Elemente"}, {"text": "Spaltenverschiebung", "correct": false, "because": "Ändert Lösung"}, {"text": "Zufällige Skalierung", "correct": false, "because": "Verfälscht Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Matrix für numerische Verfahren geeignet?', 5, '[{"text": "Nicht-Singularität", "correct": true, "because": "Garantieren Lösbarkeit"}, {"text": "Symmetrie", "correct": true, "because": "Vereinfacht Berechnungen"}, {"text": "Zufällige Einträge", "correct": false, "because": "Keine Vorteile"}, {"text": "Hohe Dimension", "correct": false, "because": "Erhöht Komplexität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Pivotisierung erhöht die Stabilität. b) Sie verdoppelt immer die Rechenzeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Lösung eines Gleichungssystems unwichtig?', 4, '[{"text": "Determinante", "correct": false, "because": "Zeigt Lösbarkeit"}, {"text": "Pivot-Elemente", "correct": false, "because": "Vermeiden Fehler"}, {"text": "Programmiersprache", "correct": true, "because": "Algorithmus ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Lösung eines linearen Systems immer exakt?', 2, '[{"text": "Nein", "correct": true, "because": "Rundungsfehler möglich"}, {"text": "Ja", "correct": false, "because": "Numerische Ungenauigkeiten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren verbessern die Effizienz bei der Lösung eines Systems?', 4, '[{"text": "Sparse Matrix Nutzung", "correct": true, "because": "Reduziert Berechnungen"}, {"text": "Optimierte Pivotwahl", "correct": true, "because": "Vermeidet Instabilität"}, {"text": "Hohe Rundung", "correct": false, "because": "Verursacht Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass numerische Verfahren immer schneller als analytische sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Systemgröße"}, {"text": "Ja", "correct": "false", "because": "Analytisch oft präziser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich, wenn ich eine Matrix umforme?', 3, '[{"text": "Dreiecksgestalt", "correct": true, "because": "Ermöglicht Rückwärtseinsetzen"}, {"text": "Maximale Einträge", "correct": false, "because": "Irrelevant"}, {"text": "Minimale Dimension", "correct": false, "because": "Ändert Problem"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Matrix eine eindeutige Lösung garantiert?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Rang"}, {"text": "Ja", "correct": false, "because": "Nicht reguläre Matrizen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aussagen treffen zu? a) Eine null-Diagonale macht die Lösung unmöglich. b) Symmetrische Matrizen sind immer lösbar.', 4, '[{"text": "Beides falsch", "correct": true, "because": "a) Pivotisierung möglich, b) nicht garantiert"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beide falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Implementierung eines Lösungsverfahrens?', 5, '[{"text": "Numerische Stabilität", "correct": true, "because": "Minimiert Fehler"}, {"text": "Effiziente Speichernutzung", "correct": true, "because": "Reduziert Ressourcen"}, {"text": "Maximale Iterationen", "correct": false, "because": "Verlangsamt Prozess"}, {"text": "Grafische Ausgabe", "correct": false, "because": "Nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich ein System ohne Pivotisierung lösen?', 3, '[{"text": "Ja", "correct": true, "because": "Aber riskant bei kleinen Elementen"}, {"text": "Nein", "correct": false, "because": "Pivotisierung nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem vermeide ich durch Zeilenvertauschung?', 4, '[{"text": "Division durch null", "correct": true, "because": "Stabilisiert Verfahren"}, {"text": "Matrixdimension", "correct": false, "because": "Unbeeinflusst"}, {"text": "Rundungsfehler", "correct": false, "because": "Nur teilweise relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass große Matrizen immer länger brauchen. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Komplexität steigt"}, {"text": "Nein", "correct": false, "because": "Optimierte Algorithmen möglich"}]');
